"use client";
import { ArtemisScope } from "./artemis-scope";
import Variant0 from "./components/animated-text/variants/01-alternating-swap";
export interface ArtemisTextSwapProps {
  className?: string;
}
export function ArtemisTextSwap({ className }: ArtemisTextSwapProps) {
  return (
    <ArtemisScope className={`art:[&>*]:mx-auto ${className ?? ""}`}>
      <div className="art:flex art:w-full art:justify-center"><Variant0 /></div>
    </ArtemisScope>
  );
}

"use client";
// @zeus-internal
import { useState } from "react";
import { motion } from "motion/react";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_SWAP } from "../../../lib/ease";
const labels = ["Explore\u00A0work", "View\u00A0projects"] as const;
function LetterRow({ text, row, active }: {
    text: string;
    row: number;
    active: boolean;
}) {
    return (<span className="art:col-start-1 art:row-start-1 art:inline-flex art:whitespace-pre">
      {Array.from(text).map((letter, index) => {
            const offset = (index % 2 === 0 ? -115 : 115) * (row === 0 ? 1 : -1);
            const visible = row === 0 ? !active : active;
            const initialY = row === 0 ? "0%" : `${offset}%`;
            return (<span className="art:inline-grid art:overflow-hidden art:align-bottom" key={`${row}-${index}`}>
            <motion.span className="art:col-start-1 art:row-start-1 art:inline-block art:will-change-[transform,filter,opacity]" initial={false} style={{ transform: `translateY(${initialY})`, opacity: row === 0 ? 1 : 0, filter: row === 0 ? "blur(0px)" : "blur(7px)" }} animate={{ transform: `translateY(${visible ? 0 : offset}%)`, opacity: visible ? 1 : 0, filter: visible ? "blur(0px)" : "blur(7px)" }} transition={{
                    transform: { ...ARTEMIS_SPRING_SWAP, delay: index * 0.012 },
                    opacity: { duration: 0.18, ease: ARTEMIS_EASE_OUT, delay: index * 0.012 },
                    filter: { duration: 0.18, ease: ARTEMIS_EASE_OUT, delay: index * 0.012 },
                }}>
              {letter}
            </motion.span>
          </span>);
        })}
    </span>);
}
export default function AnimatedTextAlternatingSwap() {
    const [active, setActive] = useState(false);
    return (<>
      <a href="#alternating-text-swap" className="art:group art:inline-flex art:min-h-12 art:items-center art:gap-3 art:border-border art:border-b art:pb-2 art:font-medium art:text-3xl art:text-foreground art:tracking-[-0.04em] art:outline-none art:@min-[640px]/artemis:text-5xl art:focus-visible:ring-2 art:focus-visible:ring-ring" onMouseEnter={() => setActive(true)} onMouseLeave={() => setActive(false)}>
        <span className="art:inline-grid">
          <span className="art:sr-only">Explore work</span>
          <span aria-hidden="true" className="art:inline-grid art:whitespace-pre">
            <LetterRow text={labels[0]} row={0} active={active}/>
            <LetterRow text={labels[1]} row={1} active={active}/>
          </span>
        </span>
        <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-arrow-up-right art:size-6 art:text-muted-foreground art:transition-transform art:duration-200 art:group-hover:translate-x-0.5 art:group-hover:-translate-y-0.5 art:@min-[640px]/artemis:size-8" aria-hidden="true">
          <path d="M7 7h10v10"/>
          <path d="M7 17 17 7"/>
        </svg>
      </a>
    </>);
}
